class Solution {
  private int k, n;
  private int[][] cnt;
  private int[] prod;

  private void pull(int node) {
    int l = 2 * node, r = 2 * node + 1;
    prod[node] = prod[l] * prod[r] % k;
    for (int x = 0; x < k; x++) cnt[node][x] = cnt[l][x];
    for (int y = 0; y < k; y++) cnt[node][prod[l] * y % k] += cnt[r][y];
  }

  private void build(int node, int lo, int hi, int[] nums) {
    if (lo == hi) {
      prod[node] = nums[lo] % k;
      cnt[node][nums[lo] % k] = 1;
      return;
    }
    int mid = (lo + hi) >>> 1;
    build(2 * node, lo, mid, nums);
    build(2 * node + 1, mid + 1, hi, nums);
    pull(node);
  }

  private void update(int node, int lo, int hi, int pos, int v) {
    if (lo == hi) {
      java.util.Arrays.fill(cnt[node], 0);
      prod[node] = v % k;
      cnt[node][v % k] = 1;
      return;
    }
    int mid = (lo + hi) >>> 1;
    if (pos <= mid) update(2 * node, lo, mid, pos, v);
    else update(2 * node + 1, mid + 1, hi, pos, v);
    pull(node);
  }

  // returns counts followed by the product at index k
  private int[] query(int node, int lo, int hi, int from) {
    if (from <= lo) {
      int[] res = java.util.Arrays.copyOf(cnt[node], k + 1);
      res[k] = prod[node];
      return res;
    }
    int mid = (lo + hi) >>> 1;
    if (from > mid) return query(2 * node + 1, mid + 1, hi, from);
    int[] a = query(2 * node, lo, mid, from);
    int[] b = query(2 * node + 1, mid + 1, hi, from);
    int[] res = new int[k + 1];
    System.arraycopy(a, 0, res, 0, k);
    for (int y = 0; y < k; y++) res[a[k] * y % k] += b[y];
    res[k] = a[k] * b[k] % k;
    return res;
  }

  public int[] resultArray(int[] nums, int k, int[][] queries) {
    this.k = k;
    n = nums.length;
    cnt = new int[4 * n][k];
    prod = new int[4 * n];
    build(1, 0, n - 1, nums);
    int[] ans = new int[queries.length];
    for (int i = 0; i < queries.length; i++) {
      update(1, 0, n - 1, queries[i][0], queries[i][1]);
      ans[i] = query(1, 0, n - 1, queries[i][2])[queries[i][3]];
    }
    return ans;
  }
}
